  if(paymentActive())return top+'<div class="st224-root"><section class="st224-hero"><span class="st224-eyebrow">Tanabi Sports</span><h1>Completa tu pedido</h1><p>Tu pago se procesa de forma segura con Stripe.</p></section>'+messages+(D.orderError?buyerOrder():'')+'</div>';
